<?php $id=(int)($_GET['id']??0);$r=null;if($id){$s=$pdo->prepare('SELECT * FROM borrowers WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)redirect('?page=borrowers');}$error='';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');$status=$_POST['status']??'Active';if($name===''||strlen($name)>120||!preg_match('/^[+0-9() .-]{7,25}$/',$phone)||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||!in_array($status,['Active','Inactive'],true))$error='Enter a name, valid contact number, optional valid email and account status.';elseif($email===''&&$r&&$r['password_hash'])$error='This borrower has an online account, so an email address is required.';elseif($email!==''&&(($dup=$pdo->prepare('SELECT COUNT(*) FROM borrowers WHERE email=? AND id<>?'))&&$dup->execute([$email,$id])&&(int)$dup->fetchColumn()>0))$error='Another borrower already uses that email address.';else{if($id){$s=$pdo->prepare('UPDATE borrowers SET full_name=?,phone=?,email=?,address=?,notes=?,status=? WHERE id=?');$s->execute([$name,$phone,$email?:null,trim($_POST['address']??'')?:null,trim($_POST['notes']??'')?:null,$status,$id]);}else{$s=$pdo->prepare('INSERT INTO borrowers(full_name,phone,email,address,notes) VALUES(?,?,?,?,?)');$s->execute([$name,$phone,$email?:null,trim($_POST['address']??'')?:null,trim($_POST['notes']??'')?:null]);$id=(int)$pdo->lastInsertId();}log_activity($pdo,$r?'Updated borrower':'Registered borrower','borrower',$id);flash('Borrower record saved.');redirect('?page=borrower-view&id='.$id);}}layout_start($id?'Edit borrower':'Add borrower','borrowers'); ?><div class="page-heading"><div><a class="back-link" href="?page=borrowers">← Borrowers</a><h1><?=$id?'Edit borrower':'Register a borrower'?></h1><p class="muted">Collect only the contact details needed for equipment lending.</p></div></div><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; ?><section class="panel form-panel"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Full name<input name="full_name" required maxlength="120" value="<?=h($r['full_name']??'')?>"></label><label>Contact number<input name="phone" required value="<?=h($r['phone']??'')?>"></label><label>Email address <small>(optional)</small><input type="email" name="email" value="<?=h($r['email']??'')?>"></label><label>Account status<select name="status"><option <?=($r['status']??'Active')==='Active'?'selected':''?>>Active</option><option <?=($r['status']??'')==='Inactive'?'selected':''?>>Inactive</option></select></label><label class="span-two">Address <small>(optional)</small><textarea name="address" rows="2"><?=h($r['address']??'')?></textarea></label><label class="span-two">Lending notes<textarea name="notes" rows="3"><?=h($r['notes']??'')?></textarea></label><div class="form-actions span-two"><a class="button ghost" href="?page=borrowers">Cancel</a><button class="button primary">Save borrower</button></div></form></section><?php layout_end();
